        self.capacity = capacity
        self.data = {}
        self.order = []  # List of keys in order of recency (front = oldest)
        self._key_to_index = {}  # Map key -> position in order list

    def get(self, key):
        if key not in self.data:
            return None
        # Move to the end of order list (making it more recent)
        old_pos = self._key_to_index[key]
